/* 적, 타워, 총알, 폭발 이펙트 객체 */
(function(){
  const E=window.TD={};
  E.PATH=[{x:-30,y:210},{x:270,y:210},{x:270,y:450},{x:870,y:450},{x:930,y:450}];
  E.pathPoint=function(distance){let d=distance;for(let i=0;i<E.PATH.length-1;i++){let a=E.PATH[i],b=E.PATH[i+1],len=Math.hypot(b.x-a.x,b.y-a.y);if(d<=len){let t=d/len;return{x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t}}d-=len}return E.PATH[E.PATH.length-1]};
  E.pathLength=810;
  E.Enemy=class{constructor(wave){this.distance=0;this.speed=35+wave*2;this.maxHp=70+wave*22;this.hp=this.maxHp;this.reward=12+wave*2;this.radius=17;this.dead=false;this.escaped=false}update(dt){this.distance+=this.speed*dt;if(this.distance>=E.pathLength)this.escaped=true}get pos(){return E.pathPoint(this.distance)}};
  E.Tower=class{constructor(x,y){this.x=x;this.y=y;this.level=1;this.damage=18;this.range=125;this.cooldown=0;this.cost=50}upgrade(){this.level++;this.damage+=12;this.range+=12;this.cooldown=0}shoot(target){this.cooldown=.62;return new E.Bullet(this.x,this.y,target,this.damage)}};
  E.Bullet=class{constructor(x,y,target,damage){this.x=x;this.y=y;this.target=target;this.damage=damage;this.speed=420;this.dead=false}update(dt){if(!this.target||this.target.dead||this.target.escaped){this.dead=true;return}let p=this.target.pos,dx=p.x-this.x,dy=p.y-this.y,d=Math.hypot(dx,dy),step=this.speed*dt;if(d<=step+8){this.target.hp-=this.damage;this.dead=true}else{this.x+=dx/d*step;this.y+=dy/d*step}}};
  E.Particle=class{constructor(x,y){this.x=x;this.y=y;this.life=.65;this.max=.65;this.r=5+Math.random()*8;this.vx=(Math.random()-.5)*100;this.vy=(Math.random()-.5)*100}update(dt){this.life-=dt;this.x+=this.vx*dt;this.y+=this.vy*dt}}
})();

/* 웨이브 진행과 적 생성 */
(function(){
  const E=window.TD;
  E.Waves=class{constructor(game){this.game=game;this.number=1;this.toSpawn=0;this.spawnTimer=0;this.active=false;this.breakTimer=0}start(number){this.number=number;this.toSpawn=5+number*2;this.spawnTimer=0;this.active=true;this.breakTimer=0}update(dt){if(!this.active){this.breakTimer-=dt;if(this.breakTimer<=0)this.start(this.number+1);return}if(this.toSpawn>0){this.spawnTimer-=dt;if(this.spawnTimer<=0){this.game.enemies.push(new E.Enemy(this.number));this.toSpawn--;this.spawnTimer=Math.max(.42,1.05-this.number*.025)}}else if(this.game.enemies.length===0){this.active=false;this.breakTimer=2.2}}};
})();

/* 캔버스의 모든 그림 */
(function(){
  const R=window.TD.Renderer={};
  R.draw=function(ctx,game){const w=900,h=600;ctx.clearRect(0,0,w,h);ctx.fillStyle='#142237';ctx.fillRect(0,0,w,h);R.grid(ctx);R.path(ctx);game.towers.forEach(t=>R.tower(ctx,t,t===game.selected));game.enemies.forEach(e=>R.enemy(ctx,e));game.bullets.forEach(b=>R.bullet(ctx,b));game.particles.forEach(p=>R.particle(ctx,p));};
  R.grid=function(c){c.strokeStyle='#233653';c.lineWidth=1;for(let x=0;x<=900;x+=60){c.beginPath();c.moveTo(x,0);c.lineTo(x,600);c.stroke()}for(let y=0;y<=600;y+=60){c.beginPath();c.moveTo(0,y);c.lineTo(900,y);c.stroke()}};
  R.path=function(c){c.save();c.lineCap='butt';c.lineJoin='round';c.strokeStyle='#6d553e';c.lineWidth=78;c.beginPath();c.moveTo(-30,210);c.lineTo(270,210);c.lineTo(270,450);c.lineTo(930,450);c.stroke();c.strokeStyle='#a57b51';c.lineWidth=66;c.stroke();c.restore();c.fillStyle='#e9d2a0';c.font='bold 14px sans-serif';c.fillText('START',12,192);c.fillText('END',850,432)};
  R.tower=function(c,t,selected){c.save();if(selected){c.beginPath();c.arc(t.x,t.y,t.range,0,Math.PI*2);c.fillStyle='#59a9ff18';c.fill();c.strokeStyle='#69b5ff88';c.stroke()}c.fillStyle='#3973b8';c.beginPath();c.arc(t.x,t.y,22,0,Math.PI*2);c.fill();c.fillStyle='#a9ddff';c.beginPath();c.arc(t.x,t.y,10,0,Math.PI*2);c.fill();c.fillStyle='#fff';c.font='bold 12px sans-serif';c.textAlign='center';c.fillText(t.level,t.x,t.y+4);c.restore()};
  R.enemy=function(c,e){let p=e.pos;c.fillStyle='#d44c62';c.beginPath();c.arc(p.x,p.y,e.radius,0,Math.PI*2);c.fill();c.fillStyle='#2a1420';c.fillRect(p.x-18,p.y-28,36,5);c.fillStyle='#63e37c';c.fillRect(p.x-18,p.y-28,36*Math.max(0,e.hp/e.maxHp),5);c.fillStyle='#fff';c.beginPath();c.arc(p.x-6,p.y-4,3,0,Math.PI*2);c.arc(p.x+6,p.y-4,3,0,Math.PI*2);c.fill()};
  R.bullet=function(c,b){c.fillStyle='#ffe16a';c.beginPath();c.arc(b.x,b.y,5,0,Math.PI*2);c.fill()};
  R.particle=function(c,p){c.globalAlpha=Math.max(0,p.life/p.max);c.fillStyle='#ffbd4a';c.beginPath();c.arc(p.x,p.y,p.r*(p.life/p.max),0,Math.PI*2);c.fill();c.globalAlpha=1};
})();

/* 게임 상태, 입력, 루프 */
(function(){
  const E=window.TD, canvas=document.getElementById('gameCanvas'),ctx=canvas.getContext('2d');
  const title=document.getElementById('titleScreen'),gameScreen=document.getElementById('gameScreen'),over=document.getElementById('gameOverScreen');
  const moneyEl=document.getElementById('moneyValue'),livesEl=document.getElementById('livesValue'),waveEl=document.getElementById('waveValue'),msg=document.getElementById('message');
  let game=null,last=0,raf=0,messageTimer=0;
  const pathCells=new Set(['0,3','1,3','2,3','3,3','4,3','4,4','4,5','5,5','6,5','7,5','8,5','9,5']);
  function newGame(){game={money:150,lives:10,enemies:[],towers:[],bullets:[],particles:[],selected:null,paused:false,waves:null,over:false};game.waves=new E.Waves(game);game.waves.start(1);title.classList.add('hidden');over.classList.add('hidden');gameScreen.classList.remove('hidden');document.getElementById('pauseOverlay').classList.add('hidden');document.getElementById('pauseButton').textContent='일시정지';updateUI();last=performance.now();cancelAnimationFrame(raf);raf=requestAnimationFrame(loop)}
  function updateUI(){moneyEl.textContent=game.money;livesEl.textContent=game.lives;waveEl.textContent=game.waves.number;const t=game.selected,p=document.getElementById('towerPanel');if(t){p.classList.remove('hidden');document.getElementById('towerLevel').textContent=t.level;document.getElementById('towerDamage').textContent=t.damage;document.getElementById('towerRange').textContent=Math.round(t.range);document.getElementById('upgradeButton').textContent='업그레이드 (💰'+(60+t.level*15)+')';document.getElementById('sellButton').textContent='판매 (+💰'+Math.floor(t.cost*.6)+')'}else p.classList.add('hidden')}
  function say(text){msg.textContent=text;msg.classList.add('show');messageTimer=2}
  function loop(now){let dt=Math.min(.05,(now-last)/1000);last=now;if(!game.paused&&!game.over)update(dt);E.Renderer.draw(ctx,game);if(messageTimer>0){messageTimer-=dt;if(messageTimer<=0)msg.classList.remove('show')}if(!game.over)raf=requestAnimationFrame(loop)}
  function update(dt){game.waves.update(dt);game.enemies.forEach(e=>e.update(dt));game.towers.forEach(t=>{t.cooldown-=dt;if(t.cooldown<=0){let target=game.enemies.filter(e=>!e.dead&&!e.escaped&&Math.hypot(e.pos.x-t.x,e.pos.y-t.y)<=t.range).sort((a,b)=>b.distance-a.distance)[0];if(target)game.bullets.push(t.shoot(target))}});game.bullets.forEach(b=>b.update(dt));game.enemies.forEach(e=>{if(e.hp<=0&&!e.dead){e.dead=true;game.money+=e.reward;for(let i=0;i<12;i++)game.particles.push(new E.Particle(e.pos.x,e.pos.y))}if(e.escaped&&!e.dead){e.dead=true;game.lives--;say('적이 끝까지 도착했어요! 목숨 -1')}});game.enemies=game.enemies.filter(e=>!e.dead&&!e.escaped);game.bullets=game.bullets.filter(b=>!b.dead);game.particles.forEach(p=>p.update(dt));game.particles=game.particles.filter(p=>p.life>0);if(game.lives<=0)endGame();updateUI()}
  function cellAt(ev){const r=canvas.getBoundingClientRect();return{x:Math.floor((ev.clientX-r.left)/r.width*15),y:Math.floor((ev.clientY-r.top)/r.height*10)}}
  canvas.addEventListener('click',function(ev){if(game.paused||game.over)return;const cell=cellAt(ev),x=cell.x*60+30,y=cell.y*60+30;if(cell.x<0||cell.x>14||cell.y<0||cell.y>9)return;const existing=game.towers.find(t=>Math.hypot(t.x-x,t.y-y)<25);if(existing){game.selected=existing;updateUI();return}if(pathCells.has(cell.x+','+cell.y)){say('길 위에는 타워를 놓을 수 없어요');return}if(game.towers.some(t=>Math.hypot(t.x-x,t.y-y)<45)){say('타워가 너무 가까워요');return}if(game.money<50){say('돈이 모자라요');return}game.money-=50;game.towers.push(new E.Tower(x,y));game.selected=game.towers[game.towers.length-1];say('타워를 설치했습니다');updateUI()});
  document.getElementById('startButton').onclick=newGame;document.getElementById('restartButton').onclick=newGame;
  document.getElementById('pauseButton').onclick=function(){if(!game||game.over)return;game.paused=!game.paused;this.textContent=game.paused?'계속하기':'일시정지';document.getElementById('pauseOverlay').classList.toggle('hidden',!game.paused);if(!game.paused)last=performance.now()};
  document.getElementById('upgradeButton').onclick=function(){if(!game.selected)return;let cost=60+game.selected.level*15;if(game.money<cost){say('돈이 모자라요');return}game.money-=cost;game.selected.upgrade();say('타워가 업그레이드됐어요');updateUI()};
  document.getElementById('sellButton').onclick=function(){if(!game.selected)return;game.money+=Math.floor(game.selected.cost*.6);game.towers=game.towers.filter(t=>t!==game.selected);game.selected=null;say('타워를 판매했습니다');updateUI()};
  function endGame(){game.over=true;const reached=game.waves.number;let best=Number(localStorage.getItem('tdBestWave')||0);if(reached>best){best=reached;localStorage.setItem('tdBestWave',best)}document.getElementById('finalWave').textContent=reached;document.getElementById('overBestWave').textContent=best;over.classList.remove('hidden');gameScreen.classList.add('hidden');cancelAnimationFrame(raf)}
  document.getElementById('titleBestWave').textContent=localStorage.getItem('tdBestWave')||0;
  window.addEventListener('beforeunload',function(){if(game&&!game.over){let best=Number(localStorage.getItem('tdBestWave')||0);if(game.waves.number>best)localStorage.setItem('tdBestWave',game.waves.number)}});
  E.Renderer.draw(ctx,{towers:[],enemies:[],bullets:[],particles:[],selected:null});
})();
